 public static function listScheduleForUser(string $uid,?string $from=null,?string $to=null):array{$m=self::request('GET','group_memberships?user_id=eq.'.rawurlencode($uid).'&is_active=eq.true&select=group_id');$ids=[];foreach($m as $x)if(isset($x['group_id']))$ids[]=(string)$x['group_id'];$ids=array_values(array_unique($ids));if(!$ids)return [];$sel='id,group_id,semester,version,created_at,schedule_entries(id,subject_id,date,start_time,end_time,type,room,building,notes,is_cancelled)';$r=self::request('GET','schedules?group_id=in.('.rawurlencode(self::q($ids)).')&select='.rawurlencode($sel).'&order=group_id.asc,semester.asc.nullslast,version.desc,created_at.desc');$latest=[];foreach($r as $x){$k=(string)$x['group_id'].':'.(string)($x['semester']??0);if(!isset($latest[$k]))$latest[$k]=$x;}$out=[];foreach($latest as $sc)foreach(($sc['schedule_entries']??[]) as $e){$d=(string)($e['date']??'');if($from&&$d<$from)continue;if($to&&$d>$to)continue;$e['schedule_id']=$sc['id']??null;$e['group_id']=$sc['group_id']??null;$e['semester']=$sc['semester']??null;$e['version']=$sc['version']??null;$out[]=$e;}usort($out,static fn($a,$b)=>strcmp((string)($a['date']??''),(string)($b['date']??''))?:strcmp((string)($a['start_time']??''),(string)($b['start_time']??'')));return $out;}
