 public static function listUsers(int $limit=100,?string $search=null,?int $course=null,?string $role=null):array{$p='users?select='.rawurlencode('id,email,full_name,course_number,created_at').'&order=created_at.desc.nullslast&limit='.(int)$limit;if($search!==null&&trim($search)!==''){$x=trim($search);$p.='&or=('.rawurlencode('email.ilike.*'.$x.'*').','.rawurlencode('full_name.ilike.*'.$x.'*').')';}if($course!==null)$p.='&course_number=eq.'.rawurlencode((string)$course);$users=self::request('GET',$p);if(!$users)return [];$ids=array_map(static fn($x)=>(string)$x['id'],$users);$rm=[];foreach(self::request('GET','roles?select=id,code') as $x)$rm[(string)$x['id']=(string)$x['code'];$by=[];foreach(self::request('GET','user_roles?user_id=in.('.rawurlencode(self::q($ids)).')&select=user_id,role_id') as $x){$c=$rm[(string)($x['role_id']??'')]??null;if($c)$by[(string)$x['user_id']][]=$c;}$out=[];foreach($users as $x){$x['roles']=$by[(string)$x['id']]??[];if($role!==null&&!in_array($role,$x['roles'],true))continue;$out[]=$x;}return $out;}
